'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var factory = require( './../lib/factory.js' );


// FIXTURES //

var data = require( './fixtures/julia/data.json' );
var smallP = require( './fixtures/julia/small_p.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof factory, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a function', function test( t ) {
	var quantile = factory( 0.0, 1.0 );
	t.strictEqual( typeof quantile, 'function', 'returns expected value' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the created function returns `NaN`', function test( t ) {
	var quantile;
	var y;

	quantile = factory( 1.0, 1.0 );
	y = quantile( NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( NaN, 1.0 );
	y = quantile( 0.2 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( 1.0, NaN );
	y = quantile( 0.2 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( NaN, NaN );
	y = quantile( 0.2 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( NaN, NaN );
	y = quantile( NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a nonpositive `b`, the created function always returns `NaN`', function test( t ) {
	var quantile;
	var y;

	quantile = factory( 1.0, 0.0 );

	y = quantile( 0.5 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( 1.0, -1.0 );

	y = quantile( 0.5 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = quantile( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( 1.0, NINF );
	y = quantile( 0.2 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( PINF, NINF );
	y = quantile( 0.2 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( NINF, NINF );
	y = quantile( 0.2 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( NaN, NINF );
	y = quantile( 0.2 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a nonpositive `a`, the created function always returns `NaN`', function test( t ) {
	var quantile;
	var y;

	quantile = factory( 0.0, 0.5 );

	y = quantile( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( -1.0, 0.5 );

	y = quantile( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = quantile( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( NINF, 1.0 );
	y = quantile( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( NINF, PINF );
	y = quantile( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( NINF, NINF );
	y = quantile( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	quantile = factory( NINF, NaN );
	y = quantile( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the created function evaluates the quantile for random `p`, `a` and `b`', function test( t ) {
	var expected;
	var quantile;
	var a;
	var b;
	var i;
	var p;
	var y;

	expected = data.expected;
	p = data.p;
	a = data.a;
	b = data.b;
	for ( i = 0; i < expected.length; i++ ) {
		quantile = factory( a[i], b[i] );
		y = quantile( p[i] );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 3 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the created function evaluates the quantile for small `p`', function test( t ) {
	var expected;
	var quantile;
	var a;
	var b;
	var i;
	var p;
	var y;

	expected = smallP.expected;
	p = smallP.p;
	a = smallP.a;
	b = smallP.b;
	for ( i = 0; i < expected.length; i++ ) {
		quantile = factory( a[i], b[i] );
		y = quantile( p[i] );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 1 ), true, 'returns expected value' );
	}
	t.end();
});
